import React, { useState } from 'react'
import styled from 'styled-components'
import { dateFormat } from '../../utils/dateFormat';
import { Investor,bitcoin, book, calender, card, circle, clothing, comment, dollar, food, freelance, medical, money, piggy, stocks, takeaway, trash, tv, users, yt, edit } from '../../utils/Icons';
import Button from '../Button/Button';

function IncomeItem({
    id,
    title,
    amount,
    date,
    category,
    description,
    deleteItem,
    updateItem,
    indicatorColor,
    type
}) {

    const categoryIcon = () =>{
        switch(category) {
            // case 'salary':
            //     return money;
            case 'Investor':
                return Investor;
            case 'freelancing':
                return freelance
            case 'investments':
                return stocks;
            case 'stocks':
                return users;
            case 'bitcoin':
                return bitcoin;
            case 'bank':
                return card;
            case 'youtube':
                return yt;
            case 'other':
                return piggy;
            default:
                return ''
        }
    }

    const expenseCatIcon = () => {
        switch (category) {
            case 'education':
                return book;
            case 'groceries':
                return food;
            case 'health':
                return medical;
            case 'subscriptions':
                return tv;
            case 'takeaways':
                return takeaway;
            case 'clothing':
                return clothing;
            case 'travelling':
                return freelance;
            case 'other':
                return circle;
            default:
                return ''
        }
    }

    const [isPopupOpen, setIsPopupOpen] = useState(false);
    const [updatedIncome, setUpdatedIncome] = useState({
        title,
        amount,
        category,
        description,
        date,
    });

    const handleUpdateClick = () => {
        setIsPopupOpen(true);
    };

    const handleClosePopup = () => {
        setIsPopupOpen(false);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUpdatedIncome({ ...updatedIncome, [name]: value });
    };

    const handleUpdateSubmit = () => {
        updateItem(id, updatedIncome);
        setIsPopupOpen(false);
    };

    console.log('type', type)

    return (
        <IncomeItemStyled indicator={indicatorColor}>
            {/* Icon */}
            <div className="icon">
    {type === 'expense' ? expenseCatIcon() : categoryIcon()}
</div>

<div className="content">
    {/* Title */}
    <div className="row">
        <div className="column">
            <p><strong>Income Title : </strong> {title}</p>
        </div>
        <div className="column">
            <p><strong>Income Amount : </strong>LKR {amount}</p>
        </div>
        <div className="column">
            <div className="btn-group">
                <Button 
                    icon={edit}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg={'var(--primary-color)'}
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={handleUpdateClick}
                />
                <Button 
                    icon={trash}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg={'var(--primary-color)'}
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={() => deleteItem(id)}
                />
            </div>
        </div>
    </div>

    {/* Transaction Date and Department */}
    <div className="row">
        <div className="column">
            <p><strong>Transaction Date : </strong> {dateFormat(date)}</p>
        </div>
        <div className="column">
            <p><strong>Department : </strong>{category}</p>
        </div>
        <div className="column">
            {/* Empty column for spacing */}
        </div>
    </div>

    {/* Description */}
    <p className="description">
        <strong>Description : </strong>
        {description}
    </p>
</div>




            {/* Update Popup */}
            {isPopupOpen && (
                <PopupStyled>
                    <div className="popup">
                        <h3>Update Income</h3>
                        <input type="text" name="title" value={updatedIncome.title} onChange={handleInputChange} placeholder="Title" />
                        <input type="number" name="amount" value={updatedIncome.amount} onChange={handleInputChange} placeholder="Amount" />
                        <input type="text" name="category" value={updatedIncome.category} onChange={handleInputChange} placeholder="Category" />
                        <input type="text" name="description" value={updatedIncome.description} onChange={handleInputChange} placeholder="Description" />
                        <input type="date" name="date" value={updatedIncome.date} onChange={handleInputChange} />
                        <div className="buttons">
                            <button onClick={handleUpdateSubmit}>Update</button>
                            <button onClick={handleClosePopup}>Close</button>
                        </div>
                    </div>
                </PopupStyled>
            )}
        </IncomeItemStyled>
    )
}

const IncomeItemStyled = styled.div`
    background: #FCF6F9;
    border: 2px solid #FFFFFF;
    box-shadow: 0px 1px 15px rgba(0, 0, 0, 0.06);
    border-radius: 20px;
    padding: 1rem;
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    gap: 1rem;
    width: 100%;
    color: #222260;

    .icon {
        width: 80px;
        height: 80px;
        border-radius: 20px;
        background: #F5F5F5;
        display: flex;
        align-items: center;
        justify-content: center;
        border: 2px solid #FFFFFF;
    }

    .content {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 0.5rem;

        h5 {
            font-size: 1.3rem;
            padding-left: 2rem;
            position: relative;
        }

        .row {
            display: flex;
            gap: 1rem;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;

            .column {
                flex: 1; /* Each column takes equal width */
                display: flex;

}

            p {
                display: flex;
                align-items: center;
                gap: 0.5rem;
                color: var(--primary-color);
                opacity: 0.8;

}
            }

            .btn-group {
                display: flex;
                gap: 1.5rem;
            }
        }

        /* Ensures long descriptions wrap properly */
        .description {
            color: var(--primary-color);
            opacity: 0.8;
            max-width: 100%;
            overflow-wrap: break-word;
            word-wrap: break-word;
            white-space: normal;
            margin-top: 0.5rem;
        }
    }
`;

const PopupStyled = styled.div`
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;

    .popup {
        background: white;
        padding: 2rem;
        border-radius: 10px;
        box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.2);
        width: 400px; /* Adjust width as needed */
        position: relative;
        z-index: 10000; /* Ensure modal is above the overlay */
    }

    input {
        width: 100%;
        padding: 10px;
        margin: 10px 0;
        border: 1px solid #ccc;
        border-radius: 5px;
    }

    .buttons {
        display: flex;
        justify-content: space-between;
    }

    button {
        padding: 10px;
        border: none;
        cursor: pointer;
        border-radius: 5px;
        width: 45%;
    }

    button:first-child {
        background: green;
        color: white;
    }

    button:last-child {
        background: red;
        color: white;
    }


`;


export default IncomeItem
